try{importScripts("/src/version.js")}catch(_){}const VERSION=typeof self!=="undefined"&&self.APP_VERSION||"6.1.1";const CACHE_STATIC=`catalogue-static-v${VERSION}`;const CACHE_MEDIA=`catalogue-media-v${VERSION}`;const ACTIVE_CACHES=[CACHE_STATIC,CACHE_MEDIA];const PRECACHE_ASSETS=["/","/index.html","/manifest.webmanifest","/src/version.js","/src/app.js","/assets/icon-192.png","/assets/icon-512.png","/assets/icon-book.png","/assets/apple-touch-icon.png"];self.addEventListener("install",event=>{event.waitUntil(caches.open(CACHE_STATIC).then(cache=>cache.addAll(PRECACHE_ASSETS).catch(err=>{console.warn("[SW] Precache tài nguyên tĩnh không hoàn tất (bỏ qua):",err)})))});self.addEventListener("activate",event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.map(key=>{if(!ACTIVE_CACHES.includes(key)){console.log("[SW] Xóa cache phiên bản cũ:",key);return caches.delete(key)}}))).then(()=>self.clients.claim()))});self.addEventListener("message",event=>{const data=event.data;if(data==="SKIP_WAITING"||data&&data.type==="SKIP_WAITING"){self.skipWaiting()}if(data==="CLEAR_CACHE"||data&&data.type==="CLEAR_CACHE"){caches.keys().then(keys=>Promise.all(keys.map(k=>caches.delete(k)))).then(()=>{console.log("[SW] Đã xóa sạch toàn bộ cache theo yêu cầu người dùng.")})}});self.addEventListener("fetch",event=>{const req=event.request;if(req.method!=="GET")return;const url=new URL(req.url);if(!url.protocol.startsWith("http"))return;if(url.pathname.startsWith("/api/")&&!url.pathname.startsWith("/api/media/"))return;if(url.hostname.includes("supabase.co"))return;if(url.pathname==="/config.js"||url.pathname==="/version.json"){event.respondWith(fetch(req,{cache:"no-store"}).catch(()=>caches.match(req)));return}if(req.mode==="navigate"){event.respondWith(fetch(req).then(res=>{if(res&&res.status===200){const clone=res.clone();caches.open(CACHE_STATIC).then(c=>c.put(req,clone))}return res}).catch(()=>caches.match(req).then(cached=>cached||caches.match("/index.html")||caches.match("/"))));return}if(url.pathname.startsWith("/api/media/")||url.pathname.startsWith("/assets/")){event.respondWith(caches.open(CACHE_MEDIA).then(cache=>cache.match(req).then(cached=>{if(cached)return cached;return fetch(req).then(netRes=>{if(netRes&&netRes.status===200){cache.put(req,netRes.clone())}return netRes}).catch(()=>null)})));return}event.respondWith(caches.match(req).then(cached=>{const fetchPromise=fetch(req).then(netRes=>{if(netRes&&netRes.status===200){const clone=netRes.clone();caches.open(CACHE_STATIC).then(c=>c.put(req,clone))}return netRes}).catch(()=>cached);return cached||fetchPromise}))});